/* @autogenerated */
import { TenantRepository } from 'app/features/identity/tenant/repository/tenant-repository.service';
import { BaseExportAction } from 'app/shared/toolkit/action/base-export-action';
import { TemplateVariable } from 'app/features/template/template-variable/model/template-variable.model';
import { ExportDefinition } from 'app/shared/toolkit/entity-export/entity-export.model';
import { take, map } from 'rxjs';
import {
  TEMPLATE_VARIABLE_EXCEL_SENSITIVE,
  TEMPLATE_VARIABLE_EXCEL_COLUMNS,
} from 'app/features/template/template-variable/model/template-variable-excel-columns';
import { Component, inject } from '@angular/core';
import { TemplateVariableRepository } from 'app/features/template/template-variable/repository/template-variable-repository.service';

@Component({
  selector: 'template-variable-view-export-action',
  standalone: false,
  templateUrl: './template-variable-view-export-action.component.html',
})
export class TemplateVariableViewExportActionComponent extends BaseExportAction<TemplateVariable> {
  protected readonly scope = 'template/template-variable';
  protected readonly repository = inject(TemplateVariableRepository);
  private readonly tenantRepository = inject(TenantRepository);

  readonly definition: ExportDefinition<TemplateVariable> = {
    name: 'template.template-variable',
    scope: this.scope,
    // Las mismas columnas que la importación: el fichero se puede editar y volver a subir
    columns: TEMPLATE_VARIABLE_EXCEL_COLUMNS,
    sensitive: TEMPLATE_VARIABLE_EXCEL_SENSITIVE,
    references: {
      tenant: {
        names: (refs) =>
          this.tenantRepository.values({ uids: refs, limit: refs.length }).pipe(
            take(1),
            map((found) => Object.fromEntries(found.map((one) => [one.uid, String(one.name ?? '')]))),
          ),
      },
    },
    source: {
      acl: () => this.repository.checkAcl(),
      list: (filter) => this.repository.list(filter).pipe(take(1)),
    },
  };
}
